using System.Text.RegularExpressions;
using ANcpLua.Roslyn.Utilities.Testing.MSBuild;
using Qyl.Telemetry.SemanticConventions.Analyzers;

namespace Qyl.Telemetry.SemanticConventions.Pipeline.Tests;
/// <summary>
/// Cross-verifies <c>OpenTelemetryDeprecatedSemconvCatalog.cs</c> against the registry's own
/// deprecations (<c>SemconvDeprecations.g.cs</c>, generated by Weaver).
/// </summary>
/// <remarks>
/// The catalog is deliberately hand-curated — it carries since-versions, guidance prose, and
/// mappings for keys upstream deleted outright, none of which the registry contains — so it
/// cannot be generated. What can rot silently is the part the registry does know:
/// <list type="number">
///   <item>every attribute the registry renames must appear in the catalog with exactly the
///   registry's replacement;</item>
///   <item>every attribute the registry deprecates without a rename must appear somewhere in
///   the catalog (exact table, context-sensitive table, or prefix rule);</item>
///   <item>every deprecated enum member must appear in the catalog's attribute-value table
///   under the same attribute.</item>
/// </list>
/// Catalog-only entries are fine: the registry cannot vouch either way. This replaces
/// scripts/verify_deprecated_catalog.py.
/// </remarks>
[TestClass]
public sealed class DeprecatedSemconvCatalogTests
{
    private static readonly Catalog Parsed = Catalog.Load();
    [TestMethod]
    public void Every_registry_rename_has_a_catalog_entry_and_known_replacements_agree()
    {
        Assert.IsNotEmpty(SemconvDeprecations.Renamed);
        var problems = new List<string>();
        foreach (var(key, renamedTo)in SemconvDeprecations.Renamed)
        {
            if (!Parsed.TryGetReplacement(key, out var known, out var replacement))
            {
                problems.Add($"MISSING rename: registry deprecates '{key}' -> '{renamedTo}', catalog has no entry");
                continue;
            }

            if (known && replacement is not null && !string.Equals(replacement, renamedTo, StringComparison.Ordinal))
                problems.Add($"MISMATCH: catalog maps '{key}' -> '{replacement}' but registry says '{renamedTo}'");
        }

        Assert.IsEmpty(problems, string.Format(System.Globalization.CultureInfo.InvariantCulture, "the analyzer catalog must agree with the registry on every rename:\n{0}", string.Join("\n", problems.Order(StringComparer.Ordinal))));
    }

    [TestMethod]
    public void Every_Registry_Deprecation_Without_A_Replacement_Is_In_The_Catalog()
    {
        Assert.IsNotEmpty(SemconvDeprecations.DeprecatedWithoutReplacement);
        var problems = SemconvDeprecations.DeprecatedWithoutReplacement.Where(key => !Parsed.TryGetReplacement(key, out _, out _)).Select(key => $"MISSING deprecation: registry deprecates '{key}', catalog has no entry").Order(StringComparer.Ordinal).ToList();
        Assert.IsEmpty(problems, string.Format(System.Globalization.CultureInfo.InvariantCulture, "the analyzer catalog must know every attribute the registry deprecates:\n{0}", string.Join("\n", problems)));
    }

    [TestMethod]
    public void Every_Registry_Enum_Member_Deprecation_Is_In_The_Catalog_Value_Table()
    {
        // The catalog files enum-value deprecations under the current attribute name; if the
        // attribute itself was renamed, the entry may live under either name.
        Assert.IsNotEmpty(SemconvDeprecations.DeprecatedValues);
        var renames = SemconvDeprecations.Renamed.ToDictionary(static entry => entry.Key, static entry => entry.RenamedTo, StringComparer.Ordinal);
        var problems = SemconvDeprecations.DeprecatedValues.Where(entry => !Parsed.Values.Contains((entry.Key, entry.Value)) && !(renames.TryGetValue(entry.Key, out var renamed) && Parsed.Values.Contains((renamed, entry.Value)))).Select(entry => $"MISSING enum-value deprecation: '{entry.Key}' member '{entry.Value}' is deprecated in the registry, catalog value-table has no entry").Order(StringComparer.Ordinal).ToList();
        Assert.IsEmpty(problems, string.Format(System.Globalization.CultureInfo.InvariantCulture, "the analyzer catalog must know every deprecated enum member:\n{0}", string.Join("\n", problems)));
    }

    /// <summary>The five data tables of the catalog, read out of the C# source by their literal shapes.</summary>
    private sealed class Catalog
    {
        private static readonly Regex PairEntry = new(@"\[""([^""]+)""\] = \(""([^""]*)"", ""[^""]*""\)", RegexOptions.Compiled);
        private static readonly Regex StringEntry = new(@"\[""([^""]+)""\] = ""((?:[^""\\]|\\.)+)""", RegexOptions.Compiled);
        private static readonly Regex ValueTable = new(@"\[""([^""]+)""\] = new\(StringComparer\.OrdinalIgnoreCase\) \{([^}]*)\}", RegexOptions.Compiled | RegexOptions.Singleline);
        private Catalog(Dictionary<string, string> exact, Dictionary<string, string> prefixes, Dictionary<string, string> genAi, HashSet<string> context, HashSet<(string, string)> values)
        {
            Exact = exact;
            Prefixes = prefixes;
            GenAi = genAi;
            Context = context;
            Values = values;
        }

        private Dictionary<string, string> Exact { get; }
        private Dictionary<string, string> Prefixes { get; }
        private Dictionary<string, string> GenAi { get; }
        private HashSet<string> Context { get; }
        internal HashSet<(string Key, string Value)> Values { get; }

        internal static Catalog Load()
        {
            var text = File.ReadAllText(RepoPath("src", "Qyl.Telemetry.SemanticConventions.Analyzers", "OpenTelemetryDeprecatedSemconvCatalog.cs"));
            var values = new HashSet<(string, string)>();
            foreach (Match table in ValueTable.Matches(Section(text, "DeprecatedAttributeValues")))
                foreach (Match entry in StringEntry.Matches(table.Groups[2].Value))
                    values.Add((table.Groups[1].Value, entry.Groups[1].Value));
            return new Catalog(Pairs(Section(text, "DeprecatedAttributes")), Pairs(Section(text, "DeprecatedAttributePrefixes")), Pairs(Section(text, "DeprecatedGenAiAttributes")), StringEntry.Matches(Section(text, "ContextSensitiveDeprecatedNames")).Select(static m => m.Groups[1].Value).ToHashSet(StringComparer.Ordinal), values);
        }

        private static Dictionary<string, string> Pairs(string section) => PairEntry.Matches(section).ToDictionary(static m => m.Groups[1].Value, static m => m.Groups[2].Value, StringComparer.Ordinal);
        private static string Section(string text, string name)
        {
            var start = text.IndexOf(name, StringComparison.Ordinal);
            Assert.IsGreaterThan(0, start, $"the catalog must declare {name}");
            var end = text.IndexOf("};", start, StringComparison.Ordinal);
            return text.Substring(start, end - start);
        }

        /// <summary>Whether the catalog knows the old name, and the replacement it claims.</summary>
        internal bool TryGetReplacement(string old, out bool known, out string? replacement)
        {
            known = true;
            if (Exact.TryGetValue(old, out var exact))
            {
                replacement = exact.Length == 0 ? null : exact;
                return true;
            }

            if (GenAi.TryGetValue(old, out var genAi))
            {
                replacement = genAi;
                return true;
            }

            if (Context.Contains(old))
            {
                // Guidance only: the catalog claims no machine replacement.
                replacement = null;
                return true;
            }

            foreach (var(prefix, replacementPrefix)in Prefixes)
            {
                if (old.StartsWith(prefix, StringComparison.Ordinal))
                {
                    replacement = string.Concat(replacementPrefix, old.AsSpan(prefix.Length));
                    return true;
                }
            }

            known = false;
            replacement = null;
            return false;
        }
    }

    internal static string RepoPath(params string[] parts)
    {
        string root = RepositoryRoot.LocateFrom(AppContext.BaseDirectory, "Qyl.Telemetry.SemanticConventions.slnx");
        return Path.Combine([root, ..parts]);
    }
}
